begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
\ir fixtures/finance.inc
create temporary table finance_result(k text primary key,v jsonb);grant all on finance_result to authenticated;
set local role authenticated;
select is(pg_temp.finance_read()#>>'{data,settings,currency}','TRY','organization base currency explicit');
insert into finance_result values('charge',pg_temp.finance_post('MANUAL_CHARGE','100000','e5000000-0000-4000-8000-000000000301','{"tax_rate_bps":2000,"tax_inclusive":true}'));
select is((select v#>>'{data,status}' from finance_result where k='charge'),'SAVED','manual charge posts');
select is((select amount_minor from public.finance_documents where id='e5000000-0000-4000-8000-000000000301'),100000::bigint,'integer gross exact');
select is((select tax_amount_minor from public.finance_documents where id='e5000000-0000-4000-8000-000000000301'),16667::bigint,'inclusive tax rounds half up');
select is((select net_amount_minor from public.finance_documents where id='e5000000-0000-4000-8000-000000000301'),83333::bigint,'net plus tax exact');
select is(pg_temp.finance_payment('PAYMENT','60000','e5000000-0000-4000-8000-000000000302','[{"charge_id":"e5000000-0000-4000-8000-000000000301","amount_minor":"60000"}]')#>>'{data,status}','SAVED','partial card payment allocates');
select is(pg_temp.finance_read()#>>'{data,client_balances,0,balance_minor}','40000','client owes 400.00 after 1000 charge and 600 payment');
select is(pg_temp.finance_payment('DEPOSIT','10000','e5000000-0000-4000-8000-000000000303')#>>'{data,status}','SAVED','deposit creates credit only');
select is(pg_temp.finance_read()#>>'{data,client_balances,0,available_credit_minor}','10000','deposit stays explicitly available');
select is(pg_temp.finance_read()#>>'{data,client_balances,0,outstanding_minor}','40000','deposit not silently allocated');
select is(pg_temp.finance('{"type":"ALLOCATE","mutation_id":"e5000000-0000-4000-8000-000000000401","client_id":"b4000000-0000-4000-8000-000000000031","payment_id":"e5000000-0000-4000-8000-000000000303","allocations":[{"charge_id":"e5000000-0000-4000-8000-000000000301","amount_minor":"10000"}],"reason":"Explicit credit application"}')#>>'{data,status}','SAVED','deposit explicitly applies');
select is(pg_temp.finance_read()#>>'{data,client_balances,0,outstanding_minor}','30000','allocation reduces charge remaining');
select is(pg_temp.finance_read('{"document_id":"e5000000-0000-4000-8000-000000000301"}')#>>'{data,documents,0,deposit_applied_minor}','10000','appointment charge projection includes exact explicit deposit application');
select is(pg_temp.finance_read()#>>'{data,client_balances,0,balance_minor}','30000','allocation never double counts account credit');
select is(pg_temp.finance_payment('PAYMENT','30000','e5000000-0000-4000-8000-000000000304','[{"charge_id":"e5000000-0000-4000-8000-000000000301","amount_minor":"30000"}]','CASH')#>>'{data,status}','SAVED','split cash payment completes charge');
select is(pg_temp.finance_read()#>>'{data,client_balances,0,balance_minor}','0','all payments settle exact account');
select is(pg_temp.finance_read()#>>'{data,cash_sessions,0,current_expected_minor}','40000','opening plus cash payment exact');
select is(pg_temp.finance_payment('PAYMENT','1','e5000000-0000-4000-8000-000000000305','[{"charge_id":"e5000000-0000-4000-8000-000000000301","amount_minor":"1"}]')->>'code','FINANCE_ALLOCATION_CONFLICT','over-allocation rejected');
select is((select count(*) from public.finance_documents where id='e5000000-0000-4000-8000-000000000305'),0::bigint,'rejected payment leaves no partial money fact');
select is(pg_temp.finance('{"type":"REFUND","mutation_id":"e5000000-0000-4000-8000-000000000402","id":"e5000000-0000-4000-8000-000000000306","original_payment_id":"e5000000-0000-4000-8000-000000000302","amount_minor":"20000","occurred_at":"2026-10-09T12:00:00Z","reason":"Actual partial card refund"}')#>>'{data,status}','SAVED','partial refund appends fact');
select is(pg_temp.finance_read()#>>'{data,client_balances,0,balance_minor}','20000','refund reopens debt exact');
select is(pg_temp.finance_read()#>>'{data,client_balances,0,outstanding_minor}','20000','refund releases allocated funds');
select is(pg_temp.finance('{"type":"REFUND","mutation_id":"e5000000-0000-4000-8000-000000000403","id":"e5000000-0000-4000-8000-000000000307","original_payment_id":"e5000000-0000-4000-8000-000000000302","amount_minor":"40001","occurred_at":"2026-10-09T12:00:00Z","reason":"Too much refund"}')->>'code','FINANCE_REFUND_LIMIT','refund cannot exceed original funds');
insert into finance_result values('permanent',pg_temp.finance('{"type":"CLIENT_CREDIT","mutation_id":"e5000000-0000-4000-8000-000000000404","id":"e5000000-0000-4000-8000-000000000308","client_id":"b4000000-0000-4000-8000-000000000031","currency":"TRY","amount_minor":"1000","description":"Administrative credit","occurred_at":"2026-10-09T12:00:00Z","reason":"Approved correction"}'));
select is(pg_temp.finance('{"type":"CLIENT_CREDIT","mutation_id":"e5000000-0000-4000-8000-000000000404","id":"e5000000-0000-4000-8000-000000000308","client_id":"b4000000-0000-4000-8000-000000000031","currency":"TRY","amount_minor":"1000","description":"Administrative credit","occurred_at":"2026-10-09T12:00:00Z","reason":"Approved correction"}'),(select v from finance_result where k='permanent'),'permanent retry returns identical accepted result');
select is(pg_temp.finance('{"type":"CLIENT_CREDIT","mutation_id":"e5000000-0000-4000-8000-000000000404","id":"e5000000-0000-4000-8000-000000000308","client_id":"b4000000-0000-4000-8000-000000000031","currency":"TRY","amount_minor":"1001","description":"Administrative credit","occurred_at":"2026-10-09T12:00:00Z","reason":"Approved correction"}')->>'code','FINANCE_CONFLICT','changed permanent retry conflicts');
select is(pg_temp.finance('{"type":"CURRENCY_SET","mutation_id":"e5000000-0000-4000-8000-000000000405","currency":"USD","expected_version":1,"reason":"Cannot convert history"}')->>'code','CURRENCY_LOCKED','currency sealed after financial activity');
select is(pg_temp.finance_post('CLIENT_DEBIT','1.5')->>'code','VALIDATION_FAILED','fractional minor units rejected');
select is(pg_temp.finance_post('CLIENT_DEBIT','1',gen_random_uuid(),'{"description":true}')->>'code','VALIDATION_FAILED','direct RPC cannot replace text with boolean');
select is(pg_temp.finance_post('CLIENT_DEBIT','1',gen_random_uuid(),'{"occurred_at":null}')->>'code','VALIDATION_FAILED','direct RPC cannot omit factual time through null');
select is(pg_temp.finance_post('CLIENT_DEBIT','1',gen_random_uuid(),'{"id":null}')->>'code','VALIDATION_FAILED','direct RPC null identifier cannot become a fallback identity');
select is(pg_temp.finance_post('CLIENT_DEBIT','10',gen_random_uuid(),'{"currency":"USD"}')->>'code','CURRENCY_MISMATCH','currency mismatch rejected');
select is(pg_temp.finance_post('CLIENT_DEBIT','10',gen_random_uuid(),'{"organization_id":"b4000000-0000-4000-8000-000000000002"}')->>'code','VALIDATION_FAILED','forged ownership rejected');
select is(pg_temp.finance_post('CLIENT_DEBIT','10',gen_random_uuid(),'{"actor":"b4000000-0000-4000-8000-000000000022"}')->>'code','VALIDATION_FAILED','forged actor rejected');
select throws_ok($$update public.finance_documents set amount_minor=1$$,'42501',null,'normal role cannot edit financial fact');
select throws_ok($$delete from public.finance_ledger_entries$$,'42501',null,'normal role cannot delete financial ledger');
select throws_ok($$insert into public.finance_ledger_entries(document_id) values(gen_random_uuid())$$,'42501',null,'normal role cannot forge ledger');
select throws_ok($$select app_private.finance_core(null,null,'{}',gen_random_uuid())$$,'42501',null,'private core unavailable');
select throws_ok($$update public.audit_events set reason='rewrite'$$,'42501',null,'audit immutable');
select ok(exists(select 1 from public.audit_events where action='finance.payment_allocated'),'allocations audited');
select ok(exists(select 1 from public.audit_events where action='finance.refund'),'refund audited');
select set_config('request.jwt.claim.sub','b4000000-0000-4000-8000-000000000022',true);
select is((select count(*) from public.finance_documents),0::bigint,'cross organization money invisible');
select is(public.finance_snapshot('b4000000-0000-4000-8000-000000000112','b4000000-0000-4000-8000-000000000011','{}')->>'code','TENANT_CONTEXT_INVALID','cross location context rejected');
select set_config('request.jwt.claim.sub','b4000000-0000-4000-8000-000000000023',true);
select is(public.finance_snapshot('b4000000-0000-4000-8000-000000000113','b4000000-0000-4000-8000-000000000011','{}')->>'code','FORBIDDEN','technical staff denied full finance');
select is((select count(*) from public.finance_documents),0::bigint,'technical staff direct finance denied');
reset role;
update public.salon_memberships set status='revoked',revoked_at=statement_timestamp() where id='b4000000-0000-4000-8000-000000000111';
set local role authenticated;
select set_config('request.jwt.claim.sub','b4000000-0000-4000-8000-000000000021',true);
select is(pg_temp.finance_read()->>'code','MEMBERSHIP_REVOKED','revoked membership rejects snapshot');
select is((select count(*) from public.finance_documents),0::bigint,'revoked direct finance denied');
select * from finish();rollback;
